-- ---------- Änderungen am Aufbau protokollieren (für „In die App übernehmen“) ----------
create table if not exists public.ws_aufbau_aenderungen (
  id bigserial primary key,
  projekt_id text not null references public.ws_projekte(id) on delete cascade,
  art text not null check (art in ('bereich_neu','bereich_name','bereich_reihe','bereich_weg','gruppe_neu','gruppe_name','gruppe_bereich','gruppe_reihe','gruppe_weg','feature_neu','feature_gruppe','feature_name','feature_weg')),
  text text not null,
  details jsonb not null default '{}'::jsonb,
  wer uuid default auth.uid(),
  erstellt timestamptz not null default now(),
  auftrag_id bigint references public.ws_auftraege(id) on delete set null
);
create index if not exists ws_aufbau_aenderungen_offen on public.ws_aufbau_aenderungen (projekt_id) where auftrag_id is null;
alter table public.ws_aufbau_aenderungen enable row level security;
drop policy if exists ws_aufbau_aenderungen_lesen on public.ws_aufbau_aenderungen;
create policy ws_aufbau_aenderungen_lesen on public.ws_aufbau_aenderungen for select to authenticated using (public.ws_sieht_projekt(projekt_id));
revoke insert, update, delete on public.ws_aufbau_aenderungen from anon, authenticated;
grant select on public.ws_aufbau_aenderungen to authenticated;

create or replace function public.ws_aufbau_log() returns trigger
language plpgsql security definer set search_path = public as $$
declare p text; n text; alt text; b_alt text; b_neu text;
begin
  if coalesce(current_setting('cs.aufbau_still', true), '') = 'an' then return coalesce(new, old); end if;
  if tg_table_name = 'ws_bereiche' then
    p := coalesce(new.projekt_id, old.projekt_id);
    if p is null or (select aufbau_datei from ws_projekte where id = p) is null then return coalesce(new, old); end if;
    if tg_op = 'INSERT' then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'bereich_neu', 'Neue Obergruppe „' || new.name || '“', jsonb_build_object('bereich', new.id));
    elsif tg_op = 'DELETE' then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'bereich_weg', 'Obergruppe „' || old.name || '“ entfernt', jsonb_build_object('bereich', old.id));
    else
      if new.name is distinct from old.name then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'bereich_name', 'Obergruppe „' || old.name || '“ heißt jetzt „' || new.name || '“', jsonb_build_object('bereich', new.id)); end if;
      if new.reihenfolge is distinct from old.reihenfolge then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'bereich_reihe', 'Reihenfolge der Obergruppe „' || new.name || '“ geändert', jsonb_build_object('bereich', new.id)); end if;
    end if;
    return coalesce(new, old);
  end if;
  if tg_table_name = 'ws_gruppen' then
    p := (select projekt_id from ws_bereiche where id = coalesce(new.bereich_id, old.bereich_id));
    if p is null or (select aufbau_datei from ws_projekte where id = p) is null then return coalesce(new, old); end if;
    if tg_op = 'INSERT' then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'gruppe_neu', 'Neue Gruppe „' || new.name || '“', jsonb_build_object('gruppe', new.id));
    elsif tg_op = 'DELETE' then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'gruppe_weg', 'Gruppe „' || old.name || '“ entfernt', jsonb_build_object('gruppe', old.id, 'app_key', old.app_key));
    else
      if new.name is distinct from old.name then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'gruppe_name', 'Gruppe „' || old.name || '“ heißt jetzt „' || new.name || '“', jsonb_build_object('gruppe', new.id, 'app_key', new.app_key)); end if;
      if new.bereich_id is distinct from old.bereich_id then
        select name into b_alt from ws_bereiche where id = old.bereich_id; select name into b_neu from ws_bereiche where id = new.bereich_id;
      elsif new.reihenfolge is distinct from old.reihenfolge then
      end if;
    end if;
    return coalesce(new, old);
  end if;
  -- ws_features
  p := (select b.projekt_id from ws_gruppen g join ws_bereiche b on b.id = g.bereich_id where g.id = coalesce(new.gruppe_id, old.gruppe_id));
  if p is null or (select aufbau_datei from ws_projekte where id = p) is null then return coalesce(new, old); end if;
  if tg_op = 'INSERT' then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'feature_neu', 'Neues Feature „' || new.name || '“ in „' || coalesce((select name from ws_gruppen where id = new.gruppe_id), '?') || '“', jsonb_build_object('feature', new.id, 'gruppe', new.gruppe_id));
  elsif tg_op = 'DELETE' then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'feature_weg', 'Feature „' || old.name || '“ entfernt', jsonb_build_object('feature', old.id));
  else
    if new.gruppe_id is distinct from old.gruppe_id then
      select name into alt from ws_gruppen where id = old.gruppe_id; select name into n from ws_gruppen where id = new.gruppe_id;
    end if;
    if new.name is distinct from old.name then insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'feature_name', 'Feature ' || new.id || ' heißt jetzt „' || new.name || '“', jsonb_build_object('feature', new.id)); end if;
  end if;
  return coalesce(new, old);
end $$;
drop trigger if exists ws_aufbau_log on public.ws_bereiche;
create trigger ws_aufbau_log after insert or update or delete on public.ws_bereiche for each row execute function public.ws_aufbau_log();
drop trigger if exists ws_aufbau_log on public.ws_gruppen;
create trigger ws_aufbau_log after insert or update or delete on public.ws_gruppen for each row execute function public.ws_aufbau_log();
drop trigger if exists ws_aufbau_log on public.ws_features;
create trigger ws_aufbau_log after insert or update of gruppe_id, name or delete on public.ws_features for each row execute function public.ws_aufbau_log();

-- Gruppe einordnen (Ziehen auf eine Obergruppe bzw. vor eine andere Gruppe): nur Admin
create or replace function public.ws_gruppe_einordnen(p_gruppe text, p_bereich text, p_vor text default null) returns void
language plpgsql security definer set search_path = public as $$
declare g ws_gruppen; r int := 0; x record;
begin
  if not public.ws_ist_admin() then raise exception 'Nur der Admin ordnet Gruppen'; end if;
  select * into g from ws_gruppen where id = p_gruppe for update;
  if g.id is null then raise exception 'Gruppe nicht gefunden'; end if;
  if (select projekt_id from ws_bereiche where id = p_bereich) is distinct from (select projekt_id from ws_bereiche where id = g.bereich_id) then raise exception 'Nur innerhalb desselben Projekts'; end if;
  if (select global from ws_bereiche where id = p_bereich) or (select global from ws_bereiche where id = g.bereich_id) then raise exception 'Globale Einstellungen werden nicht verschoben'; end if;
  if g.bereich_id <> p_bereich then update ws_gruppen set bereich_id = p_bereich where id = p_gruppe; end if;
  for x in select id from ws_gruppen where bereich_id = p_bereich and id <> p_gruppe order by reihenfolge, name loop
    if x.id = p_vor then r := r + 1; update ws_gruppen set reihenfolge = r where id = p_gruppe and reihenfolge is distinct from r; end if;
    r := r + 1; update ws_gruppen set reihenfolge = r where id = x.id and reihenfolge is distinct from r;
  end loop;
  if p_vor is null or not exists (select 1 from ws_gruppen where id = p_vor and bereich_id = p_bereich) then
    update ws_gruppen set reihenfolge = r + 1 where id = p_gruppe and reihenfolge is distinct from r + 1;
  end if;
end $$;

-- Obergruppe anlegen / umbenennen / Reihenfolge / entfernen (leer): nur Admin
create or replace function public.ws_bereich_anlegen(p_projekt text, p_name text, p_teil text default 'app') returns text
language plpgsql security definer set search_path = public as $$
declare i text; n text := btrim(coalesce(p_name, '')); r int;
begin
  if not public.ws_ist_admin() then raise exception 'Nur der Admin legt Obergruppen an'; end if;
  if length(n) < 2 or length(n) > 40 then raise exception 'Name 2–40 Zeichen'; end if;
  if p_teil not in ('app', 'erp') then raise exception 'Obergruppe gehört zur App oder zum ERP'; end if;
  i := (case when p_teil = 'erp' then 'erp-' else '' end) || left(regexp_replace(translate(lower(n), 'äöüß', 'aous'), '[^a-z0-9]+', '-', 'g'), 30);
  i := btrim(i, '-');
  while exists (select 1 from ws_bereiche where id = i) loop i := i || '-2'; end loop;
  select coalesce(max(reihenfolge), 0) + 1 into r from ws_bereiche where projekt_id = p_projekt and app_teil = p_teil;
  return i;
end $$;
create or replace function public.ws_bereich_aendern(p_bereich text, p_name text default null, p_reihe int default null) returns void
language plpgsql security definer set search_path = public as $$
declare b ws_bereiche; x record; r int := 0;
begin
  if not public.ws_ist_admin() then raise exception 'Nur der Admin ändert Obergruppen'; end if;
  select * into b from ws_bereiche where id = p_bereich for update;
  if b.id is null or b.global then raise exception 'Obergruppe nicht änderbar'; end if;
  if p_name is not null then
    if length(btrim(p_name)) < 2 or length(btrim(p_name)) > 40 then raise exception 'Name 2–40 Zeichen'; end if;
    update ws_bereiche set name = btrim(p_name) where id = p_bereich;
  end if;
  if p_reihe is not null then
    -- an Position p_reihe (1 = oben) innerhalb des Teils (App bzw. ERP) setzen
    for x in select id from ws_bereiche where projekt_id = b.projekt_id and app_teil is not distinct from b.app_teil and id <> b.id order by reihenfolge, name loop
      r := r + 1; if r = greatest(1, p_reihe) then r := r + 1; end if;
      update ws_bereiche set reihenfolge = (case when b.app_teil = 'erp' then 20 else 0 end) + r where id = x.id and reihenfolge is distinct from (case when b.app_teil = 'erp' then 20 else 0 end) + r;
    end loop;
    update ws_bereiche set reihenfolge = (case when b.app_teil = 'erp' then 20 else 0 end) + least(greatest(1, p_reihe), r + 1) where id = p_bereich;
  end if;
end $$;
create or replace function public.ws_bereich_entfernen(p_bereich text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.ws_ist_admin() then raise exception 'Nur der Admin entfernt Obergruppen'; end if;
  if exists (select 1 from ws_gruppen where bereich_id = p_bereich) then raise exception 'Die Obergruppe enthält noch Gruppen – zuerst verschieben'; end if;
  if (select global from ws_bereiche where id = p_bereich) then raise exception 'Globale Einstellungen bleiben'; end if;
  delete from ws_rechte where bereich_id = p_bereich;
  delete from ws_bereiche where id = p_bereich;
end $$;
create or replace function public.ws_gruppe_umbenennen(p_gruppe text, p_name text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.ws_ist_admin() then raise exception 'Nur der Admin benennt Gruppen um'; end if;
  if length(btrim(coalesce(p_name, ''))) < 2 or length(btrim(p_name)) > 60 then raise exception 'Name 2–60 Zeichen'; end if;
  update ws_gruppen set name = btrim(p_name) where id = p_gruppe;
end $$;

-- Offene Änderungen an einen Auftrag hängen („In die App übernehmen“): nur Admin, Auftrag muss zum Projekt gehören
create or replace function public.ws_aufbau_uebergeben(p_projekt text, p_auftrag bigint) returns int
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if not public.ws_ist_admin() then raise exception 'Nur der Admin übernimmt den Aufbau'; end if;
  if (select b.projekt_id from ws_auftraege a join ws_gruppen g on g.id = a.gruppe_id join ws_bereiche b on b.id = g.bereich_id where a.id = p_auftrag) is distinct from p_projekt then raise exception 'Auftrag gehört nicht zum Projekt'; end if;
  update ws_aufbau_aenderungen set auftrag_id = p_auftrag where projekt_id = p_projekt and auftrag_id is null;
  get diagnostics n = row_count;
  return n;
end $$;

revoke all on function public.ws_gruppe_einordnen(text, text, text), public.ws_bereich_anlegen(text, text, text), public.ws_bereich_aendern(text, text, int),
  public.ws_bereich_entfernen(text), public.ws_gruppe_umbenennen(text, text), public.ws_aufbau_uebergeben(text, bigint), public.ws_aufbau_log() from public, anon;
grant execute on function public.ws_gruppe_einordnen(text, text, text), public.ws_bereich_anlegen(text, text, text), public.ws_bereich_aendern(text, text, int),
  public.ws_bereich_entfernen(text), public.ws_gruppe_umbenennen(text, text), public.ws_aufbau_uebergeben(text, bigint) to authenticated;

commit;
