        insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'gruppe_bereich', 'Gruppe „' || new.name || '“ von „' || coalesce(b_alt, '?') || '“ nach „' || coalesce(b_neu, '?') || '“', jsonb_build_object('gruppe', new.id, 'app_key', new.app_key, 'von', old.bereich_id, 'nach', new.bereich_id));
        insert into ws_aufbau_aenderungen (projekt_id, art, text, details) values (p, 'gruppe_reihe', 'Reihenfolge in „' || coalesce((select name from ws_bereiche where id = new.bereich_id), '?') || '“ geändert', jsonb_build_object('gruppe', new.id, 'bereich', new.bereich_id));
